Every function reads `dis.get_instructions` for the function's code object. Loop detection relies on backward jumps being how CPython 3.11+ encodes loops (`JUMP_BACKWARD`), so the body range is derived directly from the instruction stream. The tests deliberately assert behaviours rather than exact bytecode so they survive minor version changes.

**`bytecode_tools.py`**

```python
from __future__ import annotations

import dis
import inspect
from collections import Counter
from collections.abc import Callable
from types import CodeType
from typing import Any


def _code(func: Callable[..., Any]) -> CodeType:
    code = getattr(func, "__code__", None)
    if not isinstance(code, CodeType):
        raise TypeError(f"{func!r} is not a Python function")
    return code


def opcode_counts(func: Callable[..., Any]) -> Counter[str]:
    """Count opcodes by name in the function's own bytecode (nested code objects excluded)."""
    return Counter(ins.opname for ins in dis.get_instructions(_code(func)))


def loaded_globals(func: Callable[..., Any]) -> list[str]:
    """Names read through LOAD_GLOBAL, unique, in first-seen order."""
    seen: dict[str, None] = {}
    for ins in dis.get_instructions(_code(func)):
        if ins.opname == "LOAD_GLOBAL":
            seen.setdefault(str(ins.argval), None)
    return list(seen)


def globals_loaded_in_loops(func: Callable[..., Any]) -> list[str]:
    """Names loaded via LOAD_GLOBAL inside a loop body, found from backward jumps."""
    instructions = list(dis.get_instructions(_code(func)))
    loops = [
        (int(ins.argval), ins.offset)
        for ins in instructions
        if ins.opname == "JUMP_BACKWARD" and isinstance(ins.argval, int)
    ]
    found: dict[str, None] = {}
    for ins in instructions:
        if ins.opname != "LOAD_GLOBAL":
            continue
        if any(start <= ins.offset <= end for start, end in loops):
            found.setdefault(str(ins.argval), None)
    return list(found)


def is_generator_function(func: Callable[..., Any]) -> bool:
    return bool(_code(func).co_flags & inspect.CO_GENERATOR)


def free_variables(func: Callable[..., Any]) -> tuple[str, ...]:
    return _code(func).co_freevars
```

**`test_bytecode_tools.py`**

```python
import pytest

from bytecode_tools import (
    free_variables,
    globals_loaded_in_loops,
    is_generator_function,
    loaded_globals,
    opcode_counts,
)

LIMIT = 3


def hot(items):
    total = 0
    for x in items:
        if x > LIMIT:
            total += len(str(x))
    return total


def hoisted(items):
    limit, length, to_str = LIMIT, len, str
    total = 0
    for x in items:
        if x > limit:
            total += length(to_str(x))
    return total


def make_counter():
    n = 0

    def inc():
        nonlocal n
        n += 1
        return n

    return inc


def gen():
    yield 1


def test_loaded_globals_include_builtins_in_first_seen_order() -> None:
    assert loaded_globals(hot) == ["LIMIT", "len", "str"]


def test_globals_loaded_in_loops() -> None:
    assert globals_loaded_in_loops(hot) == ["LIMIT", "len", "str"]


def test_hoisting_moves_global_loads_out_of_the_loop() -> None:
    assert globals_loaded_in_loops(hoisted) == []
    assert set(loaded_globals(hoisted)) == {"LIMIT", "len", "str"}


def test_opcode_counts_are_names_to_positive_ints() -> None:
    counts = opcode_counts(hot)
    assert counts["LOAD_GLOBAL"] == 3
    assert counts["RETURN_VALUE"] + counts.get("RETURN_CONST", 0) >= 1
    assert all(isinstance(v, int) and v > 0 for v in counts.values())


def test_generator_and_closure_detection() -> None:
    assert is_generator_function(gen) and not is_generator_function(hot)
    assert free_variables(make_counter()) == ("n",)
    assert free_variables(hot) == ()


def test_non_function_is_rejected() -> None:
    with pytest.raises(TypeError):
        loaded_globals(42)  # type: ignore[arg-type]
```

Run the tests with `pytest -q`.

Each key has at most one in-flight `Future`. The first caller creates it and computes outside the lock; later callers find it and block on `future.result()`. On success the value is stored and the in-flight record removed; on failure only the record is removed, so errors are shared with current waiters but never cached. This is the same shape as Go's `singleflight` and as request coalescing in caches. It stays correct on a free-threaded build because all shared dictionaries are touched only under the lock.

**`singleflight.py`**

```python
from __future__ import annotations

import threading
from collections.abc import Callable, Hashable
from concurrent.futures import Future
from typing import Generic, TypeVar

K = TypeVar("K", bound=Hashable)
V = TypeVar("V")


class SingleFlightCache(Generic[K, V]):
    """Thread-safe memoizer: one computation per key, even under concurrent callers."""

    def __init__(self, compute: Callable[[K], V]) -> None:
        self._compute = compute
        self._lock = threading.Lock()
        self._values: dict[K, V] = {}
        self._inflight: dict[K, Future[V]] = {}

    def get(self, key: K) -> V:
        with self._lock:
            if key in self._values:
                return self._values[key]
            future = self._inflight.get(key)
            leader = future is None
            if future is None:
                future = self._inflight[key] = Future()
        if leader:
            self._run_leader(key, future)
        return future.result()  # waiters block here; exceptions propagate

    def _run_leader(self, key: K, future: Future[V]) -> None:
        try:
            value = self._compute(key)  # runs outside the lock: other keys proceed
        except BaseException as exc:
            with self._lock:
                del self._inflight[key]  # failures are not cached
            future.set_exception(exc)
        else:
            with self._lock:
                self._values[key] = value
                del self._inflight[key]
            future.set_result(value)

    def invalidate(self, key: K) -> None:
        with self._lock:
            self._values.pop(key, None)

    def __len__(self) -> int:
        with self._lock:
            return len(self._values)
```

**`test_singleflight.py`**

```python
import threading
import time

from singleflight import SingleFlightCache


def run_threads(n: int, target) -> None:
    threads = [threading.Thread(target=target) for _ in range(n)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=10)
    assert not any(t.is_alive() for t in threads)


def test_same_key_computed_once_under_contention() -> None:
    calls: list[str] = []

    def compute(key: str) -> int:
        calls.append(key)
        time.sleep(0.05)  # widen the race window
        return len(key)

    cache = SingleFlightCache(compute)
    barrier = threading.Barrier(8)
    results: list[int] = []

    def worker() -> None:
        barrier.wait()
        results.append(cache.get("abc"))

    run_threads(8, worker)
    assert results == [3] * 8
    assert calls == ["abc"]
    assert cache.get("abc") == 3 and calls == ["abc"]


def test_different_keys_compute_concurrently() -> None:
    both_inside = threading.Barrier(2, timeout=5)

    def compute(key: str) -> str:
        both_inside.wait()  # only passes if both computations overlap
        return key.upper()

    cache = SingleFlightCache(compute)
    out: dict[str, str] = {}

    def make(k: str):
        return lambda: out.__setitem__(k, cache.get(k))

    threads = [threading.Thread(target=make(k)) for k in ("a", "b")]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=10)
    assert out == {"a": "A", "b": "B"}


def test_exception_reaches_all_waiters_and_is_not_cached() -> None:
    attempts = 0
    gate = threading.Event()

    def compute(key: str) -> int:
        nonlocal attempts
        attempts += 1
        gate.wait(timeout=5)
        if attempts == 1:
            raise RuntimeError("upstream down")
        return 7

    cache = SingleFlightCache(compute)
    errors: list[BaseException] = []

    def worker() -> None:
        try:
            cache.get("k")
        except RuntimeError as exc:
            errors.append(exc)

    threads = [threading.Thread(target=worker) for _ in range(4)]
    for t in threads:
        t.start()
    time.sleep(0.1)
    gate.set()
    for t in threads:
        t.join(timeout=10)
    assert len(errors) == 4 and attempts == 1
    assert cache.get("k") == 7  # a later call retries
    assert attempts == 2


def test_invalidate_forces_recompute() -> None:
    n = 0

    def compute(key: int) -> int:
        nonlocal n
        n += 1
        return key * 2

    cache = SingleFlightCache(compute)
    assert cache.get(2) == 4 and cache.get(2) == 4 and n == 1
    cache.invalidate(2)
    assert cache.get(2) == 4 and n == 2
    assert len(cache) == 1
```

